172	  const float eps = 0.0001;
173	
174	  float ret = 0;
175	  float term = 1;
176	  float m = 0;
177	
178	  while (term  > eps * ret) {
179	    ret += term;
180	    ++m;
181	    term *= (x*x) / (4*m*m);
182	  }
183	  return ret;
184	}
