856	// main loop for measurement
857	bool sweep(bool break_on_operation)
858	{
859	  int i, delay;
860	  // blink LED while scanning
861	  palClearPad(GPIOC, GPIOC_LED);
862	  // Power stabilization after LED off, also align timings on i == 0
863	  for (i = 0; i < sweep_points; i++) {         // 5300
864	    if (frequencies[i] == 0) break;
865	    delay = set_frequency(frequencies[i]);     // 700
866	    tlv320aic3204_select(0);                   // 60 CH0:REFLECT, reset and begin measure
867	    dsp_start(delay + ((i == 0) ? 1 : 0));     // 1900
868	    //================================================
869	    // Place some code thats need execute while delay
870	    //================================================
871	    dsp_wait();
872	    // calculate reflection coefficient
873	    (*sample_func)(measured[0][i]);            // 60
874	
875	    tlv320aic3204_select(1);                   // 60 CH1:TRANSMISSION, reset and begin measure
876	    dsp_start(DELAY_CHANNEL_CHANGE);           // 1700
877	    //================================================
878	    // Place some code thats need execute while delay
879	    //================================================
880	    dsp_wait();
881	    // calculate transmission coefficient
882	    (*sample_func)(measured[1][i]);            // 60
883	                                               // ======== 170 ===========
884	    if (cal_status & CALSTAT_APPLY)
885	      apply_error_term_at(i);
886	
887	    if (electrical_delay != 0)
888	      apply_edelay_at(i);
889	
890	    // back to toplevel to handle ui operation
891	    if (operation_requested && break_on_operation)
892	      return false;
893	  }
894	  // blink LED while scanning
895	  palSetPad(GPIOC, GPIOC_LED);
896	  return true;
897	}
