1394	static void
1395	cal_interpolate(int s)
1396	{
1397	  const properties_t *src = caldata_ref(s);
1398	  int i, j;
1399	  int eterm;
1400	  if (src == NULL)
1401	    return;
1402	
1403	  ensure_edit_config();
1404	
1405	  // lower than start freq of src range
1406	  for (i = 0; i < sweep_points; i++) {
1407	    if (frequencies[i] >= src->_frequencies[0])
1408	      break;
1409	
1410	    // fill cal_data at head of src range
1411	    for (eterm = 0; eterm < 5; eterm++) {
1412	      cal_data[eterm][i][0] = src->_cal_data[eterm][0][0];
1413	      cal_data[eterm][i][1] = src->_cal_data[eterm][0][1];
1414	    }
1415	  }
1416	
1417	  j = 0;
1418	  for (; i < sweep_points; i++) {
1419	    uint32_t f = frequencies[i];
1420	    if (f == 0) goto interpolate_finish;
1421	    for (; j < src->_sweep_points-1; j++) {
1422	      if (src->_frequencies[j] <= f && f < src->_frequencies[j+1]) {
1423	        // found f between freqs at j and j+1
1424	        float k1 = (float)(f - src->_frequencies[j])
1425	                        / (src->_frequencies[j+1] - src->_frequencies[j]);
1426	
1427	        // avoid glitch between freqs in different harmonics mode
1428	        if (IS_HARMONIC_MODE(src->_frequencies[j]) != IS_HARMONIC_MODE(src->_frequencies[j+1])) {
1429	          // assume f[j] < f[j+1]
1430	          k1 = IS_HARMONIC_MODE(f) ? 1.0 : 0.0;
1431	        }
1432	
1433	        float k0 = 1.0 - k1;
1434	        for (eterm = 0; eterm < 5; eterm++) {
1435	          cal_data[eterm][i][0] = src->_cal_data[eterm][j][0] * k0 + src->_cal_data[eterm][j+1][0] * k1;
1436	          cal_data[eterm][i][1] = src->_cal_data[eterm][j][1] * k0 + src->_cal_data[eterm][j+1][1] * k1;
1437	        }
1438	        break;
1439	      }
1440	    }
1441	    if (j == src->_sweep_points-1)
1442	      break;
1443	  }
1444	
1445	  // upper than end freq of src range
1446	  for (; i < sweep_points; i++) {
1447	    // fill cal_data at tail of src
1448	    for (eterm = 0; eterm < 5; eterm++) {
1449	      cal_data[eterm][i][0] = src->_cal_data[eterm][src->_sweep_points-1][0];
1450	      cal_data[eterm][i][1] = src->_cal_data[eterm][src->_sweep_points-1][1];
1451	    }
1452	  }
1453	interpolate_finish:
1454	  cal_status |= src->_cal_status | CALSTAT_APPLY | CALSTAT_INTERPOLATED;
1455	  redraw_request |= REDRAW_CAL_STATUS;
1456	}
