2228	//
2229	// Read command line from shell_stream
2230	//
2231	static int VNAShell_readLine(char *line, int max_size)
2232	{
2233	  // Read line from input stream
2234	  uint8_t c;
2235	  char *ptr = line;
2236	  while (1) {
2237	    // Return 0 only if stream not active
2238	    if (streamRead(shell_stream, &c, 1) == 0)
2239	      return 0;
2240	    // Backspace or Delete
2241	    if (c == 8 || c == 0x7f) {
2242	      if (ptr != line) {
2243	        static const char backspace[] = {0x08, 0x20, 0x08, 0x00};
2244	        shell_printf(backspace);
2245	        ptr--;
2246	      }
2247	      continue;
2248	    }
2249	    // New line (Enter)
2250	    if (c == '\r') {
2251	      shell_printf(VNA_SHELL_NEWLINE_STR);
2252	      *ptr = 0;
2253	      return 1;
2254	    }
2255	    // Others (skip)
2256	    if (c < 0x20)
2257	      continue;
2258	    // Store
2259	    if (ptr < line + max_size - 1) {
2260	      streamPut(shell_stream, c); // Echo
2261	      *ptr++ = (char)c;
2262	    }
2263	  }
2264	  return 0;
2265	}
2266	
2267	//
2268	// Parse and run command line
2269	//
2270	static void VNAShell_executeLine(char *line)
2271	{
2272	  // Parse and execute line
2273	  char *lp = line, *ep;
2274	  shell_nargs = 0;
2275	  while (*lp != 0) {
2276	    // Skipping white space and tabs at string begin.
2277	    while (*lp == ' ' || *lp == '\t') lp++;
2278	    // If an argument starts with a double quote then its delimiter is another quote, else
2279	    // delimiter is white space.
2280	    ep = (*lp == '"') ? strpbrk(++lp, "\"") : strpbrk(lp, " \t");
2281	    // Store in args string
2282	    shell_args[shell_nargs++] = lp;
2283	    // Stop, end of input string
2284	    if ((lp = ep) == NULL) break;
2285	    // Argument limits check
2286	    if (shell_nargs > VNA_SHELL_MAX_ARGUMENTS) {
2287	      shell_printf("too many arguments, max " define_to_STR(
2288	          VNA_SHELL_MAX_ARGUMENTS) "" VNA_SHELL_NEWLINE_STR);
2289	      return;
2290	    }
2291	    // Set zero at the end of string and continue check
2292	    *lp++ = 0;
2293	  }
2294	  if (shell_nargs == 0) return;
2295	  // Execute line
2296	  const VNAShellCommand *scp;
2297	  for (scp = commands; scp->sc_name != NULL; scp++) {
2298	    if (strcmp(scp->sc_name, shell_args[0]) == 0) {
2299	      if (scp->flags & CMD_WAIT_MUTEX) {
2300	        shell_function = scp->sc_function;
2301	        // Wait execute command in sweep thread
2302	        do {
2303	          osalThreadSleepMilliseconds(100);
2304	        } while (shell_function);
2305	      } else {
2306	        scp->sc_function(shell_nargs - 1, &shell_args[1]);
2307	      }
2308	      return;
2309	    }
2310	  }
2311	  shell_printf("%s?" VNA_SHELL_NEWLINE_STR, shell_args[0]);
2312	}
